solution.code:
const state = { user: 'Ada', tags: ['js'] };

function updateTag(state, tag) {
  return { ...state, tags: [...state.tags, tag] };
}

const next = updateTag(state, 'css');
console.log(next.tags);  // ['js', 'css']
console.log(state.tags); // ['js']

