console.log('defaults:', defaults); // { theme: 'light', size: 'm' }  preserved

function merge(...objects) {
  return objects.reduce((acc, obj) => ({ ...acc, ...obj }), {});
}

const a = { x: 1, y: 1 };
const b = { y: 2, z: 3 };
console.log(merge(a, b)); // { x: 1, y: 2, z: 3 }
console.log(a, b);        // unchanged: {x:1,y:1} {y:2,z:3}
